// j2go: instanceof helper for Dialog and its subclasses within the translated set.
func dialogImplAsDialog(x any) (*Dialog, bool) {
	if h, ok := x.(*dialogHooked); ok {
		x = h.hook
	}
	switch v := x.(type) {
	case *Dialog:
		if v == nil {
			return nil, false
		}
		return v, true
	case *ColorDialog:
		if v == nil {
			return nil, false
		}
		return &v.Dialog, true
	case *FontDialog:
		if v == nil {
			return nil, false
		}
		return &v.Dialog, true
	case *MessageBox:
		if v == nil {
			return nil, false
		}
		return &v.Dialog, true
	case *FileDialog:
		if v == nil {
			return nil, false
		}
		return &v.Dialog, true
	case *DirectoryDialog:
		if v == nil {
			return nil, false
		}
		return &v.Dialog, true
	case *PrintDialog:
		if v == nil {
			return nil, false
		}
		return &v.Dialog, true
	}
	if l, ok := x.(interface{ AsDialog() *Dialog }); ok {
		return l.AsDialog(), true
	}
	return nil, false
}

func castanyToDialog(x any) *Dialog {
	if x == nil {
		return nil
	}
	v, ok := dialogImplAsDialog(x)
	if !ok {
		panic("java.lang.ClassCastException: Dialog")
	}
	return v
}

